    {
        #region Consts
        public const string PERMISSION_ADD = "STA_Item_Add";
        public const string PERMISSION_DELETE = "STA_Item_Delete";
        public const string PERMISSION_EDIT = "STA_Item_Edit";
        public const string PERMISSION_VIEW = "STA_Item_View";

        #endregion

        #region Variables

        DataTable dtbData;
        bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmSTAItem _instance = null;

        public static frmSTAItem Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmSTAItem();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion


        public frmSTAItem()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            gvData.OptionsView.NewItemRowPosition = UserSession.HasPermission(PERMISSION_ADD) ? DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.Top : DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.None;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                ModifyGrid();
            }
        }

        private void ModifyGrid()
        {
            if (gvData.Columns[STA_Item.C_id] == null)
                return;
            if (gvData.Columns[STA_Item.C_id].ColumnEdit == null || bolIsRefresh)
                SMS_ItemService.InitRepositoryLookUpEdit(gvData, STA_Item.C_id, SMS_Item.C_ItemName);
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = new STA_Item().Search();
                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "STA_Item", bolIsRefresh);
                    ModifyGrid();
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        /// <summary>
        /// Xóa từng dòng được chọn, bị lỗi chỗ nào thì ngưng chỗ ấy lại
        /// </summary>
        /// <returns></returns>
        private bool DeleteData()
        {
            STA_Item obj = new STA_Item();
            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = arrRowIndex.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null)
                {
                    if (drw.RowState != DataRowState.Added)
                    {
                        if (!obj.Delete(Convert.ToString(drw[STA_Item.C_ten])))
                        {
                            ErrorManager.Error("Dữ liệu đang sử dụng bạn không xóa được!");
                            return false;
                        }
                    }
                    gvData.DeleteRow(arrRowIndex[i]);
                }
            }
            return true;
        }

        /// <summary>
        /// Save dữ liệu ở lưới
        /// </summary>
        private bool SaveData()
        {
            if (dtbData != null)
            {
                STA_Item item0 = new STA_Item();
                item0.BeginTransaction();
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (drw.RowState != DataRowState.Deleted)
                    {
                        STA_Item item = new STA_Item();
                        item.IDB = item0.IDB;
                        if (item.Parse(drw))
                        {
                            if (drw.RowState == DataRowState.Added)
                            {
                                if (!item.Add())
                                {
                                    ErrorManager.Error("Việc thêm thông tin bị lỗi!");
                                    return false;
                                }
                            }
                            else if (drw.RowState == DataRowState.Modified)
                            {
                                if (!item.Update())
                                {
                                    ErrorManager.Error("Việc cập nhật thông tin bị lỗi!");
                                    return false;
                                }
                            }
                        }
                    }
                }
                item0.CommitTransaction();
                return true;
            }
            return true;
        }

        private string CheckValidate(DataRow drw)
        {
            if (drw == null)
                return "";
            STA_Item item = new STA_Item();
            if (item.Parse(drw))
            {
                if (item.Ten == "" || item.Ten == null)
                    return "Bạn phải nhập tên hàng trạm!";
            }
            return "";
        }

        /// <summary>
        /// Chọn nhiều dòng -> chuột phải Chọn hàng -> gán cùng 1 SMS_Item.ItemID
        /// </summary>
        private void ApplyItemToSelectedRows()
        {
            if (gvData.SelectedRowsCount <= 0)
            {
                MessageManager.Warning("Bạn phải chọn ít nhất một dòng!");
                return;
            }
            if (!UserSession.HasPermission(PERMISSION_EDIT))
            {
                MessageManager.Warning("Bạn không có quyền cập nhật!");
                return;
            }

            StockManager.Declaration.frmItemSelect frm = StockManager.Declaration.frmItemSelect.Instance;
            frm.ISMultiSelect = false;
            frm.ShowDialog();
            if (!frm.IsOk || frm.ItemSelected == null || frm.ItemSelected.ItemID == null)
                return;

            int intItemID = Convert.ToInt32(frm.ItemSelected.ItemID);
            string strItemCode = frm.ItemSelected.ItemCode;
            string strItemName = frm.ItemSelected.ItemName;

            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = 0; i < arrRowIndex.Length; i++)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null && drw.RowState != DataRowState.Deleted)
                {
                    drw[STA_Item.C_id] = intItemID;
                    if (dtbData.Columns.Contains("ItemCode"))
                        drw["ItemCode"] = strItemCode;
                    if (dtbData.Columns.Contains("ItemName"))
                        drw["ItemName"] = strItemName;
                }
            }

            btnSave.Enabled = mnuItemSave.Enabled = true;
            MessageManager.Info(String.Format("Đã gán hàng hóa [{0}] cho {1} dòng. Bấm Lưu để cập nhật.", strItemName, arrRowIndex.Length));
        }

        private void UpdateSelectItemMenu()
        {
            mnuItemSelectItem.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_EDIT);
        }

        #endregion

        #region Form Actions

        private void frmSTAItem_Load(object sender, EventArgs e)
        {
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
            CheckPermission();
            SetToolTip();
            UpdateSelectItemMenu();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
        {
            mnuItemDelete.Enabled = btnDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_DELETE);
            UpdateSelectItemMenu();
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            if (MessageManager.Confirm("Bạn thực sự muốn xóa những dữ liệu này?") == DialogResult.Yes)
            {
                DeleteData();
            }
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                new Thread(LoadData).Start();
                btnSave.Enabled = mnuItemSave.Enabled = false;
            }
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void mnuItemSelectItem_Click(object sender, EventArgs e)
        {
            ApplyItemToSelectedRows();
        }

        private void frmSTAItem_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.F4:
                    if (btnDelete.Enabled)
                        btnDelete_Click(sender, null);
                    break;
                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F6:
                    if (mnuItemSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
                case Keys.F7:
                    if (mnuItemSelectItem.Enabled)
                        mnuItemSelectItem_Click(sender, null);
                    break;
                case Keys.F8:
                    gvData.AddNewRow();
                    break;
                case Keys.Escape:
                    break;
            }
        }

        #endregion

        #region Grid Actions

        private void gvData_ShowingEditor(object sender, CancelEventArgs e)
        {
            if (!gvData.IsNewItemRow(gvData.FocusedRowHandle))
            {
                if (!UserSession.HasPermission(PERMISSION_EDIT))
                    e.Cancel = true;
                else
                {
                    switch (gvData.FocusedColumn.FieldName)
                    {
                        case STA_Item.C_ten:
                            e.Cancel = true;
                            break;
                        case "ItemCode":
                        case "ItemName":
                            e.Cancel = true;
                            break;
                    }
                }
            }
        }

        private void gvData_ValidatingEditor(object sender, DevExpress.XtraEditors.Controls.BaseContainerValidateEditorEventArgs e)
        {
            if (gvData.FocusedRowHandle == -999997)
                return;
            string strError = "";
            switch (gvData.FocusedColumn.FieldName)
            {
                case STA_Item.C_ten:
                    e.Valid = Libs.ValidationHelper.ValidateEmptyString(e.Value, "Tên hàng trạm không được bỏ trống!", ref strError);
                    if (e.Valid == true)
                    {
                        if (gvData.SearchRow(STA_Item.C_ten, e.Value, gvData.FocusedRowHandle) >= 0)
                        {
                            strError = "Đã tồn tại tên hàng trạm này!";
                            e.Valid = false;
                        }
                    }
                    break;
            }

            if (strError != "")
                e.ErrorText = strError;
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            string strError = CheckValidate(gvData.GetFocusedDataRow());
            if (strError != "")
            {
                e.ErrorText = strError;
                e.Valid = false;
            }
            else
                btnSave.Enabled = mnuItemSave.Enabled = true;
        }

        private void gvData_InvalidRowException(object sender, DevExpress.XtraGrid.Views.Base.InvalidRowExceptionEventArgs e)
        {
            e.ExceptionMode = DevExpress.XtraEditors.Controls.ExceptionMode.DisplayError;
        }

        private void gvData_CellValueChanged(object sender, DevExpress.XtraGrid.Views.Base.CellValueChangedEventArgs e)
        {
            if (e.Column == null || e.Column.FieldName != STA_Item.C_id)
                return;

            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw == null)
                return;

            if (e.Value == null || Convert.IsDBNull(e.Value))
            {
                if (dtbData.Columns.Contains("ItemCode"))
                    drw["ItemCode"] = DBNull.Value;
                if (dtbData.Columns.Contains("ItemName"))
                    drw["ItemName"] = DBNull.Value;
                return;
            }

            DataRow[] rows = SMS_ItemService.Table.Select(String.Format("ItemID = {0}", e.Value));
            if (rows.Length > 0)
            {
                if (dtbData.Columns.Contains("ItemCode"))
                    drw["ItemCode"] = rows[0][SMS_Item.C_ItemCode];
                if (dtbData.Columns.Contains("ItemName"))
                    drw["ItemName"] = rows[0][SMS_Item.C_ItemName];
            }
        }

        #endregion
    }
